"""Distance Between Two Nodes — depths measured from the LCA.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def findDistance(self, root, p: int, q: int) -> int:
        def contains(node, value) -> bool:
            if not node:
                return False
            return (node.val == value or contains(node.left, value)
                    or contains(node.right, value))

        if not contains(root, p) or not contains(root, q):
            return -1

        def lca(node):
            if not node or node.val in (p, q):
                return node
            left, right = lca(node.left), lca(node.right)
            if left and right:
                return node
            return left or right

        def depth(node, value, level=0) -> int:
            if not node:
                return -1
            if node.val == value:
                return level
            found = depth(node.left, value, level + 1)
            return found if found != -1 else depth(node.right, value, level + 1)

        meeting = lca(root)
        return depth(meeting, p) + depth(meeting, q)
